import {createReadStream,createWriteStream} from 'node:fs';
import {readFile,unlink} from 'node:fs/promises';
import {Readable,Transform} from 'node:stream';
import {pipeline} from 'node:stream/promises';
import {createHash} from 'node:crypto';
import {query} from '../client.js';
function required(value,name){if(!value||value===true)throw new Error('Provide --'+name);return value;}
async function mapping(file){if(!file)return {};const value=JSON.parse(await readFile(file,'utf8'));if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('Mapping file must contain an object of exported IDs to destination IDs');return value;}
export async function exportCommand({args,options,client,print}) {
  const projectId=required(args[0],'project (positional ID)'),format=options.format??'json';
  if(!['json','csv'].includes(format))throw new Error('--format must be json or csv');
  const response=await client.get('/projects/'+encodeURIComponent(projectId)+'/export'+query({format}),{response:true});
  if(!options.output){await pipeline(Readable.fromWeb(response.body),process.stdout,{end:false});return;}
  const output=required(options.output,'output'),hash=createHash('sha256');let bytes=0,created=false;
  const counter=new Transform({transform(chunk,encoding,callback){bytes+=chunk.length;hash.update(chunk);callback(null,chunk);}});
  const destination=createWriteStream(output,{flags:'wx',mode:0o600});
  destination.once('open',()=>{created=true;});
  try{await pipeline(Readable.fromWeb(response.body),counter,destination);}
  catch(error){if(created)await unlink(output).catch(()=>{});throw error;}
  print({output,format,bytes,sha256:hash.digest('hex')});
}
exportCommand.help=`crew export PROJECT [--format json|csv] [--output NEW_FILE]
Streams a project export to stdout or a newly created private file. Existing output files are never overwritten. JSON includes comments, labels, relations and user/workflow identity catalogs. CSV protects leading spreadsheet formula characters and quotes multiline cells. Attachment bytes and sprint history are outside this format.`;
export async function importCommand({args,options,client,print}) {
  const filename=required(options.file??args[0],'file'),orgId=required(options.org,'org');
  if(!options.preview&&!options.yes)throw new Error('Use --preview to validate first, or --yes to create the imported project');
  const document=JSON.parse(await readFile(filename,'utf8'));
  if(document?.format!=='crew.project'||document.version!==1)throw new Error('Expected a Crew project JSON export version1');
  const metadata={key:required(options.key,'key'),name:options.name??document.project.name,
    userMap:await mapping(options['user-map']),externalIssueMap:await mapping(options['external-map']),preview:Boolean(options.preview)};
  async function* body(){
    yield '{"document":';
    for await(const chunk of createReadStream(filename))yield chunk;
    for(const [key,value] of Object.entries(metadata))yield ','+JSON.stringify(key)+':'+JSON.stringify(value);
    yield '}';
  }
  const result=await client.request('POST','/orgs/'+encodeURIComponent(orgId)+'/import',Readable.from(body()),{stream:true,headers:{'Content-Type':'application/json'}});
  print(result);
}
importCommand.help=`crew import --org ID --file EXPORT.json --key NEWKEY [--name NAME] [--user-map MAP.json] [--external-map MAP.json] --preview|--yes
Preview validates the entire document, closure/cycles and mappings without writing. Actual import is one atomic transaction. Source IDs map to newly generated IDs; number gaps, parents, labels, authors, dates and board ranks are preserved. User maps resolve only current non-guest organization members; omitted user maps use exact email matching. Every exported external relation endpoint requires an explicit writable issue mapping. Mapping files are JSON objects keyed by exported IDs. Current JSON request limit is2MiB.`;
export async function dashboardCommand({args,options,client,print}) {
  if(args.length&&args[0]!=='show')throw new Error('Usage: crew dashboard [show] --org ID');
  print(await client.get('/dashboard'+query({orgId:required(options.org,'org'),projectId:options.project,weeks:options.weeks,date:options.date,sprintId:options.sprint})));
}
dashboardCommand.help='crew dashboard [show] --org ID [--project ID] [--weeks 1..52] [--date YYYY-MM-DD] [--sprint ID]\nCounts reflect current accessible issues; weekly throughput uses persisted completion events and sprint burndown reuses the canonical ledger.';

export const IMPORT_MAX_BYTES=2*1024*1024;
export function parseProjectFile(text) {
  let document;
  try{document=JSON.parse(text);}catch{throw new Error('Choose a valid JSON project export.');}
  if(document?.format!=='crew.project'||document.version!==1)throw new Error('Expected a Crew project export version 1.');
  for(const key of ['statuses','users','issues','labels','comments','relations'])if(!Array.isArray(document[key]))throw new Error('The export is missing its '+key+' array.');
  if(!document.project?.key||!document.project?.name)throw new Error('The export is missing project metadata.');
  return document;
}
export function importRequest({document,key,name,userMap={},externalIssueMap={}}) {
  if(!document)throw new Error('Choose a project JSON file first.');
  if(!key?.trim())throw new Error('Enter a new project key.');
  if(!name?.trim())throw new Error('Enter the imported project name.');
  return {document,key:key.trim(),name:name.trim(),userMap:Object.fromEntries(Object.entries(userMap).filter(([,value])=>value)),externalIssueMap:Object.fromEntries(Object.entries(externalIssueMap).filter(([,value])=>value))};
}
export function transferCounts(document) {
  return Object.fromEntries(['issues','labels','comments','relations','statuses'].map(key=>[key,document[key]?.length??0]));
}

import {useState} from 'preact/hooks';
import {Page,Field,Button,Notice,Empty,Loading,useLoad} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {IMPORT_MAX_BYTES,parseProjectFile,importRequest,transferCounts} from './transfer-state.js';
function TransferErrors({error}) {
  return <><Notice error={error}/>{error?.details&&<ul className="field-errors">{Object.entries(error.details).map(([key,message])=><li key={key}>{key}: {String(message)}</li>)}</ul>}</>;
}
function MappingForm({document,userMap,setUserMap,externalIssueMap,setExternalIssueMap,members}) {
  return <section><h3>Identity mapping</h3><p>Users map by exact email to a current organization member unless you select a replacement. Guests cannot author or own imported work in a newly created project.</p>
    {document.users.map(user=><Field key={user.id} label={user.name+' · '+user.email}><select value={userMap[user.id]??''} onChange={event=>setUserMap({...userMap,[user.id]:event.currentTarget.value})}>
      <option value="">Match current member by email</option>{members.filter(member=>member.role!=='guest').map(member=><option key={member.userId??member.id} value={member.userId??member.user?.id??member.id}>{member.user?.name??member.name??member.userId} · {member.role}</option>)}
    </select></Field>)}
    {(document.externalIssues??[]).length>0&&<><h3>Linked issues outside this project</h3><p>Each external endpoint needs an explicit writable issue ID in the destination organization. These mappings may add relations to those existing issues.</p>
      {document.externalIssues.map(issue=><Field key={issue.id} label={issue.key+' · '+issue.title} value={externalIssueMap[issue.id]??''} required onInput={event=>setExternalIssueMap({...externalIssueMap,[issue.id]:event.currentTarget.value})}/>)}</>}
  </section>;
}
function ImportPreview({preview}) {
  return <section className="transfer-preview"><h3>Validated import preview</h3><p>{preview.project.key} · {preview.project.name}</p>
    <dl>{Object.entries(preview.counts).map(([key,value])=><div key={key}><dt>{key}</dt><dd>{value}</dd></div>)}</dl>
    <ul>{preview.warnings.map(warning=><li key={warning}>{warning}</li>)}</ul>
    <h4>Resolved people</h4><table><thead><tr><th>Exported person</th><th>Destination account</th></tr></thead><tbody>{preview.users.map(user=><tr key={user.id}><td>{user.email}</td><td>{user.targetId}</td></tr>)}</tbody></table>
    {preview.externalIssues.length>0&&<><h4>Resolved external links</h4><ul>{preview.externalIssues.map(issue=><li key={issue.id}>{issue.key} → {issue.targetId}</li>)}</ul></>}
  </section>;
}
export function TransferPage({api,query}) {
  const [orgId,setOrgId]=useState(query.orgId??''),[projectId,setProjectId]=useState(query.projectId??'');
  const [document,setDocument]=useState(null),[filename,setFilename]=useState(''),[key,setKey]=useState(''),[name,setName]=useState('');
  const [userMap,setUserMap]=useState({}),[externalIssueMap,setExternalIssueMap]=useState({});
  const [preview,setPreview]=useState(null),[previewBody,setPreviewBody]=useState(null),[result,setResult]=useState(null);
  const [error,setError]=useState(null),[busy,setBusy]=useState(false),[confirmed,setConfirmed]=useState(false);
  const orgs=useLoad(()=>api.get('/orgs?limit=200'),[]);
  const projects=useLoad(()=>orgId?api.get('/projects?'+queryString({orgId,archived:'all',limit:200})):Promise.resolve({items:[]}),[orgId]);
  const members=useLoad(async()=>{
    if(!orgId)return {items:[]};
    const items=[];let cursor='';const seen=new Set();
    do{const page=await api.get('/orgs/'+encodeURIComponent(orgId)+'/members?'+queryString({cursor,limit:200}));items.push(...page.items);cursor=page.nextCursor;if(cursor&&seen.has(cursor))throw new Error('Repeated member cursor');seen.add(cursor);}while(cursor);
    return {items};
  },[orgId]);
  function invalidate(){setPreview(null);setPreviewBody(null);setConfirmed(false);setResult(null);}
  async function chooseFile(event){
    invalidate();setError(null);const file=event.currentTarget.files?.[0];
    if(!file){setDocument(null);setFilename('');return;}
    if(file.size>IMPORT_MAX_BYTES){setError(new Error('Project imports currently accept JSON files up to 2 MiB.'));return;}
    try{const value=parseProjectFile(await file.text());setDocument(value);setFilename(file.name);setKey(value.project.key+'COPY');setName(value.project.name+' copy');setUserMap({});setExternalIssueMap({});}
    catch(failure){setError(failure);setDocument(null);}
  }
  async function validate(event){
    event.preventDefault();setBusy(true);setError(null);invalidate();
    try{const body=importRequest({document,key,name,userMap,externalIssueMap});const response=await api.post('/orgs/'+encodeURIComponent(orgId)+'/import',{...body,preview:true});setPreview(response.preview);setPreviewBody(body);}
    catch(failure){setError(failure);}finally{setBusy(false);}
  }
  async function performImport(){
    if(!previewBody||!confirmed)return;
    setBusy(true);setError(null);
    try{const response=await api.post('/orgs/'+encodeURIComponent(orgId)+'/import',previewBody);setResult(response);setPreview(null);setPreviewBody(null);setConfirmed(false);projects.reload();}
    catch(failure){setError(failure);}finally{setBusy(false);}
  }
  return <Page title="Project transfer"><Field label="Organization"><select value={orgId} onChange={event=>{setOrgId(event.currentTarget.value);setProjectId('');invalidate();}}><option value="">Choose organization</option>{orgs.data?.items.map(org=><option key={org.id} value={org.id}>{org.name}</option>)}</select></Field>
    <TransferErrors error={error??orgs.error??projects.error??members.error}/>
    {!orgId?<Empty>Choose an organization to export or import a project.</Empty>:<>
      <section><h2>Export project</h2><p>JSON preserves workflow, issues, comments, labels, relations and identity catalogs for a validated import. CSV contains spreadsheet-safe issue rows. Attachments and sprint history are outside the transfer format.</p>
        {projects.loading?<Loading/>:<Field label="Source project"><select value={projectId} onChange={event=>setProjectId(event.currentTarget.value)}><option value="">Choose project</option>{projects.data?.items.map(project=><option value={project.id} key={project.id}>{project.key} · {project.name}</option>)}</select></Field>}
        <div className="insight-actions">{projectId?<><a className="button" href={'/api/v1/projects/'+encodeURIComponent(projectId)+'/export?format=json'} download>Download JSON</a><a className="button" href={'/api/v1/projects/'+encodeURIComponent(projectId)+'/export?format=csv'} download>Download CSV</a></>:<Empty>Select a project to download an export.</Empty>}</div>
      </section>
      <section><h2>Import a new project</h2><p>The server validates and remaps a JSON export before an atomic import. An error leaves no partial project. Importing creates new IDs and keeps original issue numbers, parent relationships, metadata and timestamps.</p>
        <form onSubmit={validate}><Field label="Crew JSON export"><input type="file" accept=".json,application/json" onChange={chooseFile}/></Field>
          {document&&<><p>{filename}: {Object.entries(transferCounts(document)).map(([key,count])=>count+' '+key).join(', ')}</p>
            <Field label="New project key" required minLength="2" maxLength="12" value={key} onInput={event=>{setKey(event.currentTarget.value);invalidate();}}/>
            <Field label="Project name" required maxLength="160" value={name} onInput={event=>{setName(event.currentTarget.value);invalidate();}}/>
            <MappingForm document={document} userMap={userMap} setUserMap={value=>{setUserMap(value);invalidate();}} externalIssueMap={externalIssueMap} setExternalIssueMap={value=>{setExternalIssueMap(value);invalidate();}} members={members.data?.items??[]}/>
            <details><summary>Included issue preview</summary><div className="transfer-preview"><table><thead><tr><th>Number</th><th>Title</th><th>Priority</th><th>Estimate</th></tr></thead><tbody>{document.issues.map(issue=><tr key={issue.id}><td>{issue.number}</td><td>{issue.title}</td><td>{issue.priority}</td><td>{issue.estimate??'—'}</td></tr>)}</tbody></table></div></details>
            <Button busy={busy} type="submit">Validate and preview</Button>
          </>}
        </form>
        {preview&&<><ImportPreview preview={preview}/><label><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.currentTarget.checked)}/> Create this new project with the displayed identity and external issue mappings.</label><Button busy={busy} disabled={!confirmed} onClick={performImport}>Import project</Button></>}
        {result&&<Notice><a href={'#/projects/'+encodeURIComponent(result.project.id)}>Open imported {result.project.key}</a>. Created {result.counts.issues} issues, {result.counts.comments} comments, {result.counts.labels} labels and {result.counts.relations} relations.</Notice>}
      </section>
    </>}
  </Page>;
}
